<script setup lang="ts">
import {onMounted,ref,onBeforeUnmount} from 'vue';import {ElButton} from 'element-plus';import {useDesktop} from './store.ts';
const store=useDesktop(),snapshot=ref<Record<string,any>>({availability:'unknown'}),items=ref<Record<string,any>[]>([]),cardKey=ref(''),scheduledAt=ref(''),timeZone=ref(Intl.DateTimeFormat().resolvedOptions().timeZone),confirm=ref(false),message=ref(''),busy=ref(false);let active=true,timer:ReturnType<typeof setTimeout>|undefined;
const stateLabels:Record<string,string>={pending:'等待预约时刻',running:'已领取执行',uncertain:'消费结果未决',succeeded:'结果已核对',failed:'未执行或失败',cancelled:'已取消',missed:'已错过'};
const outcomeLabels:Record<string,string>={reset:'已执行重置',nothingToReset:'当前无需重置',noCredit:'指定卡不可用',alreadyRedeemed:'原键已成功重置',not_written:'确定未写入',uncertain:'结果未决'};
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await work();}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
async function read(refresh=false){snapshot.value=await store.request(refresh?'resetCards.refresh':'resetCards.list');items.value=(await store.request('resetAppointments.list',{limit:200})).items as Record<string,any>[];}
async function poll(){try{await read();}catch(e){message.value=(e as Error).message;snapshot.value={availability:'unknown'};}if(active)timer=setTimeout(()=>{void poll();},1000);}
onMounted(()=>void poll());onBeforeUnmount(()=>{active=false;clearTimeout(timer);});
async function create(){await run(async()=>{if(!confirm.value)throw new Error('请明确确认本张卡的消费预约');await store.request('resetAppointments.create',{cardKey:cardKey.value,scheduledAt:new Date(scheduledAt.value).toISOString(),timeZone:timeZone.value,confirm:true},crypto.randomUUID());confirm.value=false;await read();message.value='预约已保存；退出或休眠错过后不补用。';});}
async function cancel(item:Record<string,any>){await run(async()=>{await store.request('resetAppointments.cancel',{id:item.id,expectedRevision:item.revision},crypto.randomUUID());await read();});}
const reconciling=ref<Record<string,any>|null>(null),confirmReconcile=ref(false);
async function reconcile(){await run(async()=>{if(!reconciling.value||!confirmReconcile.value)throw new Error('请确认核对可能完成原消费');await store.request('resetAppointments.reconcile',{id:reconciling.value.id,confirmMayComplete:true},crypto.randomUUID());reconciling.value=null;confirmReconcile.value=false;await read();});}
</script>
<template><section class="panel"><h2>指定卡预约</h2><p class="notice">{{store.mode==='fixture'?'模拟卡片，不影响真实额度。':'真实卡片必须显式配置来源，并在真实消费验收授权后使用。'}}仅使用指定卡；结果不确定时保留原卡原键，禁止换卡绕过。</p><p role="status">{{snapshot.availability==='known'?'卡片观察有效':'卡片状态未知'}} · {{snapshot.source||'unknown'}} {{snapshot.error||''}}</p><ElButton :disabled="busy" @click="run(()=>read(true))">刷新卡片明细</ElButton>
 <ul class="check-list"><li v-for="card in snapshot.items||[]" :key="card.cardKey"><label><input v-model="cardKey" type="radio" :value="card.cardKey" :disabled="card.status!=='available'" :aria-label="'选择'+card.title" />{{card.title}} · {{card.status}} · 尾号 {{card.idSuffix}} · {{card.expiresAt||'无到期信息'}}</label></li></ul>
 <label>预约时间（本机）<input v-model="scheduledAt" type="datetime-local" step="1" aria-label="卡片预约时间" /></label><label>时间区<input v-model="timeZone" aria-label="卡片预约时区" /></label><p class="muted">预约按绝对时刻执行；时区变化不会移动已保存预约。应用退出或休眠错过不补用。</p><label><input v-model="confirm" type="checkbox" aria-label="确认指定卡消费预约" />明确授权在此时刻消费所选卡片一次</label><ElButton :disabled="busy||!cardKey||!scheduledAt||!confirm" type="primary" @click="create">保存指定卡预约</ElButton><p v-if="message" role="alert">{{message}}</p></section>
 <section class="panel"><h2>预约与消费核对</h2><article v-for="item in items" :key="item.id" class="panel"><p>预约 {{new Date(item.scheduledAt).toLocaleString()}} · {{item.timeZone}} · {{stateLabels[item.state]||item.state}}</p><p class="mono">{{item.id}}</p><p>修订 {{item.revision}} · {{item.reason}} · 结果 {{outcomeLabels[item.outcome]||item.outcome||'尚无'}} · 领取次数 {{item.calls}}</p><ElButton v-if="item.state==='pending'" @click="cancel(item)">取消未领取预约</ElButton><ElButton v-if="item.state==='uncertain'" @click="reconciling=item;confirmReconcile=false">核对原消费</ElButton></article><p v-if="!items.length">暂无预约。</p></section>
 <section v-if="reconciling" class="panel" role="dialog" aria-label="核对原消费确认"><h2>核对原消费</h2><p>只使用原卡片和原幂等键。底层核对可能完成原先结果未知的消费。</p><label><input v-model="confirmReconcile" type="checkbox" />我确认可能完成这笔原消费</label><ElButton :disabled="!confirmReconcile||busy" @click="reconcile">确认核对原消费</ElButton><ElButton @click="reconciling=null">返回</ElButton></section></template>
